    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the residual space after placement. 
    // Minimizing this follows the Best-Fit principle.
    let mut score = post_residual as f64;

    // Penalty for opening a new bin:
    // We scale the penalty based on progress to be more conservative early on,
    // and more willing to open new bins late in the stream to prevent fragmentation.
    if is_new_bin {
        score += 25.0 * (1.0 - (progress * 0.5));
    }

    // Lookahead coupling:
    // If the next item is large, penalize small post_residuals that would orphan the next item.
    // If the current post_residual cannot fit the next item, add a non-linear penalty.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size as f64 - post_residual as f64).powf(1.5);
    }

    // Global state coupling:
    // If we have many bins open, prioritize filling the ones with the smallest residuals (Best-Fit).
    // If fitting_bins_count is low, we are running out of options; prioritize maintaining 
    // a balanced distribution by penalizing bins that deviate significantly from the mean_residual.
    if !is_new_bin {
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // Final scaling: favor bins that leave very little space (perfect fits) 
    // or leave enough space to potentially accommodate future items.
    // Exponentially penalize "dead zones" (e.g., leaving 5-15 units, which is hard to fill).
    if post_residual > 0 && post_residual < 15 {
        score += (15.0 - post_residual as f64).powi(2);
    }

    score
}

