    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward exact or near-exact fits for the lookahead item
            score -= (100.0 - (post_residual - next_item_size) as f64) * 0.5;
        } else {
            // Penalize creating "dead space" that cannot fit the next item
            score += 20.0;
        }
    }

    // 2. Harmonic Class Logic: Prefer bins that result in "clean" residuals (divisible by common factors)
    // This helps pack future items of similar sizes.
    if post_residual > 0 {
        let remainder = post_residual % 10;
        if remainder == 0 {
            score -= 15.0;
        } else if remainder >= 5 {
            score += 5.0;
        }
    }

    // 3. Thresholding: Avoid opening a new bin unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // unless all other open bins result in very poor fits.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 45.0; 
        } else {
            score -= 10.0;
        }
    }

    // 4. Density Balancing: If we have many open bins, penalize further fragmentation.
    let density_penalty = (open_bins_count as f64) * (bin_capacity - bin_residual) as f64 / 100.0;
    score += density_penalty;

    // 5. Progression adjustment: As the stream nears the end, prioritize tightest fit regardless of fragmentation.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.2);

    score
