        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // New bin logic:
    // If bin_residual == bin_capacity, it's a new bin. 
    // We only open a new bin if the current 'post' quality is significantly worse 
    // than the average residual, or if we are nearing the end of the stream 
    // and have many open bins.
    if bin_residual == bin_capacity {
        // High cost to open a new bin early, but cheapens as we exhaust existing bins
