    // Specifically, if post_residual < 10, it's likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Harmonic Class Logic: Reward placing items into bins that leave residuals 
    // that are multiples of common item sizes (e.g., 20, 25, 33).
