    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Pressure management: If fitting_bins_count is low, we are running out of 
    // options for this item. Penalize new bin creation (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 30.0 * (open_bins_count as f64 / (total_items as f64 / 10.0 + 1.0));
    }

