        if next_item_size > 0 {
            if post < next_item_size as f64 {
                // Penalize "dead space" that cannot fit the next item.
                score += (next_item_size as f64 - post).powf(1.5);
            } else {
                // Reward configurations that leave exactly enough space for the next item.
                score -= (post - next_item_size as f64).sqrt() * 2.0;
            }
        }

        // Favor bins that align with the mean density of current open bins.
        // This helps keep bins balanced in terms of remaining capacity.
        let density_diff = (post - mean_residual).abs();
        score += density_diff * 0.5;

        // If this is the last bin that fits the item, make it slightly more attractive
        // to prevent opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
