    // 1. Dead space avoidance: Penalize leaving small gaps that are unlikely to fit future items.
    // If post_residual is < 10, it is likely unusable (given item range 10-100).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead optimization: If a future item exists, reward bins that leave enough space for it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Reward perfect alignment for the next item
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 20.0; // Penalize blocking the next item
        }
    }

    // 3. Bin count pressure: If we are near the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * progress * 2.0;

    // 4. New bin logic: Only open a new bin if the fit is truly terrible.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin is based on how many bins we already have open.
        // If we have many bins open, opening another is discouraged.
        score = 45.0 + (open_bins_count as f64 * 0.5);
    } else {
        // If this is the only bin that fits the item, make it very attractive.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // 5. Mean residual balance: Favor bins that stay close to the average usage.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

