pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: Favor smaller post-residuals (Best Fit)
    // We want to minimize post_residual, but penalize tiny "sliver" residuals
    // that are too small to fit typical future items (e.g., < 10).
    let mut score = post;

    // Penalty for slivers: If post_residual is positive but smaller than the smallest 
    // likely item (10), it is "dead space".
    if post > 0.0 && post < 10.0 {
        score += 20.0 * (1.0 - (post / 10.0));
    }

    // Lookahead coupling: If a known next item exists, reward bins that leave
    // enough room for it.
    if next_item_size > 0 {
        if post >= next_item_size as f64 {
            score -= 15.0 * (1.0 - (post - next_item_size as f64) / bin_capacity as f64);
        } else {
            // Penalize if we block the next item from fitting here
            score += 25.0;
        }
    }

    // Progress-based scaling: As the stream nears the end, prioritize closing bins
    // by being more aggressive about filling existing residuals.
    let fill_pressure = progress * 10.0;
    score += (mean_residual - post) * fill_pressure;

    // New Bin Logic: Only open a new bin if the current fit is extremely poor
    // or if we are forced to.
    if bin_residual == bin_capacity {
        // This is a new bin. Assign a high base cost, adjusted by how many bins are already open.
        // We only want to open a new bin if the existing bins have very poor fit scores.
        score = 45.0 + (open_bins_count as f64 * 0.5);
    } else {
        // Existing bin: reward if fitting_bins_count is low (last chance to use this bin)
        if fitting_bins_count == 1 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    // We want to minimize post_residual (tightest fit).
    let mut score = post_res;

    // Penalty for creating "dead space": if the post_residual is too small to fit any likely item, 
    // it effectively becomes wasted. We penalize small residuals that are > 0.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Dynamic adjustment based on stream progress.
    // Early in the stream, we are more aggressive about packing tightly.
    // Late in the stream, we prioritize closing bins to reduce open_bins_count.
    let tightness_factor = (1.0 - progress) * 10.0;
    score += post_res * tightness_factor;

    // Lookahead coupling: if the next item is large, prioritize keeping bins open that have 
    // large residuals to accommodate it, rather than filling a bin to the brim now.
    if next_item_size > 50 && post_residual < 40 {
        score += 30.0 * (1.0 - progress);
    }

    // Heuristic for new bin creation: 
    // If the bin is new (bin_residual == bin_capacity), it is only selected if the 
    // cost of fitting into existing bins is higher than this threshold.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if we have many bins already open,
        // unless fitting_bins_count is very low.
        score = 45.0 + (open_bins_count as f64 * 2.5) - (fitting_bins_count as f64 * 5.0);
    } else {
        // Reward bins that bring the mean residual closer to the ideal 
        // (which is 0, but practically we want to maximize utilization).
        score += (post_res - mean_residual).abs() * 0.5;
    }

    score
}
